kithicor/Gandari.pl.source:
#!/usr/bin/perl
# items: 10569, 10546, 10033, 3189, 10566, 10570, 10034, 3181, 10548, 10568, 10032, 3188, 10571, 10567, 10035, 3184

# START of FILE Zone:kithicor  ID:20095 -- Gandari

sub EVENT_SAY { 
    if($text=~/hail/i) {
		quest::say("Most call me Gandari the Terse.  You here for [ivy armor]?");
    } 
	if($text=~/ivy armor/i) {
		quest::say("I reward brave rangers with ivy etched armor - [Helm]s. [Tunic]s. [Sleeves] and [Bracers]. [Interested]?");
    } 
	if($text=~/bracers/i) {
		quest::say("I do not haggle, I do not bargain. The Bottom of the Rune of Ivy from the plains of Everfrost, a Watery Ring from the Cauldron of Tears and a Fire Emerald to warm my heart. Bring these to me and you shall earn your reward.");
    } 
	if($text=~/helm/i) {
		quest::say("I do not haggle, I do not bargain. The Top of the Rune of Ivy from the Castle Mistmoore, a Cyclops Charm from Tarskuk and a Sapphire of Sky Blue. Bring these to me and you shall earn your reward.");
    } 
	if($text=~/sleeve/i) {
		quest::say("I do not haggle, I do not bargain. A Heart of Fire from the Caverns of Solusek, the Left side of the Rune of Ivy from the Griffon Grimfeather and two Star Rubies of sparkling hue. Bring these to me and you shall earn your reward.");
    } 
	if($text=~/tunic/i) {
		quest::say("I do not haggle, I do not bargain. The Skull of Meldrath, the Right side of the Rune of Ivy from the Thistle Brownie and two Rubies of Fiery Red. Bring these to me and you shall earn your reward.");
    }
}

sub EVENT_ITEM {
    if(plugin::check_handin(\%itemcount, 10569 => 1, 10546 => 1, 10033 => 1)) { # bracers
		quest::summonitem("3189");
		quest::ding();
		quest::say("Well done. May Karana bless your soul.");
		quest::faction(269,+30); # kithicor residence
		quest::faction(302,+30); # protectors of the pine
		quest::faction(272,+30); # jaggedpine treefolk
		quest::faction(324,-60); # unkempt druids
		quest::exp(10000);		
    } 
	if(plugin::check_handin(\%itemcount, 10566 => 1, 10570 => 1, 10034 => 1)) { # helm
		quest::summonitem("3181");
		quest::ding();
		quest::say("Well done. May Karana bless your soul.");
		quest::faction(269,+30); # kithicor residence
		quest::faction(302,+30); # protectors of the pine
		quest::faction(272,+30); # jaggedpine treefolk
		quest::faction(324,-60); # unkempt druids
		quest::exp(10000);
    } 
	if(plugin::check_handin(\%itemcount, 10548 => 1, 10568 => 1, 10032 => 2)) { # sleeves
		quest::summonitem("3188");
		quest::ding();
		quest::say("Well done. May Karana bless your soul.");
		quest::faction(269,+30); # kithicor residence
		quest::faction(302,+30); # protectors of the pine
		quest::faction(272,+30); # jaggedpine treefolk
		quest::faction(324,-60); # unkempt druids
		quest::exp(10000);		
    }
	if(plugin::check_handin(\%itemcount, 10571 => 1, 10567 => 1, 10035 => 2)) { # tunic
		quest::summonitem("3184");
		quest::ding();
		quest::say("Well done. May Karana bless your soul.");
		quest::faction(269,+30); # kithicor residence
		quest::faction(302,+30); # protectors of the pine
		quest::faction(272,+30); # jaggedpine treefolk
		quest::faction(324,-60); # unkempt druids
		quest::exp(10000);
    } 
	plugin::return_items(\%itemcount);
}

# END of FILE Zone:kithicor  ID:20095 -- Gandari

kithicor/Leaf_Falldim.pl.source:
# items: 3190, 3192, 3191
sub EVENT_SAY { 
    if($text=~/Hail/i){
	quest::say("Greetings. $name!  Respect the woods and all its inhabitants or face the wrath of the rangers.  Do not end up like [Maldyn Greenburn].");
    }
    if($text=~/maldyn greenburn/i){
	quest::say("Maldyn was once one of us.  He was the finest of archers.  Everyone aspired to be like him.  He soon was tempted to hunt.  The animals of these woods found themselves nothing more than moving targets for Maldyn's training.  We held a trial and exiled him to parts unknown.  He would take with him Morin's [Bow of Kithicor].  I was asked to find a worthy ranger to [retrieve the bow].");
    }
    if($text=~/bow of kithicor/i){
	quest::say("The Bow of Kithicor was carved from an ancient tree. It has great powers which were but a portion of the tree's mana. I seek a brave ranger to [retrieve the bow].");
    }
    if($text=~/retrieve the bow/i){
	quest::say("Search the lands of the Unkempt Druids in the Rathe Mountains.  I have heard of his arrows being found inside its territories and  of his death wish to hunt down its leader.  Retrieve the bow and return it to me and I shall give you the ivy etched gauntlets.");
    }
}

sub EVENT_ITEM {
	if(plugin::takeItems(12321 => 1, 12320 => 1)) {
		quest::summonitem(3190); # Item: Ivy Etched Gauntlets
		quest::say("Very good, you have brought justice to these lands.");
		quest::faction(269,+30); # kithicor residence
		quest::faction(302,+30); # protectors of the pine
		quest::faction(272,+30); # jaggedpine treefolk
		quest::faction(324,-60); # unkempt druids
		quest::exp(10000);		
    }
	elsif(plugin::takeItemsCoin(0,0,2000,0, 12305 => 1, 12306 => 1)) {
		quest::say("Here are your boots.");
		quest::summonitem(3192); # Item: Ivy Etched Boots
		quest::say("Very good, you have brought justice to these lands.");
		quest::faction(269,+30); # kithicor residence
		quest::faction(302,+30); # protectors of the pine
		quest::faction(272,+30); # jaggedpine treefolk
		quest::faction(324,-60); # unkempt druids
		quest::exp(10000);		
    }
    elsif(plugin::takeItems(10059 => 1, 12328 => 1)) {
		quest::say("Here are your leggings.");
		quest::summonitem(3191); # Item: Ivy Etched Leggings
		quest::say("Very good, you have brought justice to these lands.");
		quest::faction(269,+30); # kithicor residence
		quest::faction(302,+30); # protectors of the pine
		quest::faction(272,+30); # jaggedpine treefolk
		quest::faction(324,-60); # unkempt druids
		quest::exp(10000);		
    }
    plugin::returnUnusedItems();
}


# END of FILE Zone:kithicor  ID:20077 -- Leaf_Falldim

lakerathe/Kyralynn.pl.source:
# Quest for 51058 Kyralynn in Lakerathe - Shaman Totemic Armor (low 30's armor)
# Kiladiveus - completed subevents for this NPC quest.  I created the ending statement since i can't find any. Same as exp.
# Kiladiveus - In OOT, need to add loot "19035 Driftwood pipe" into "69148 isle goblin chieftan" need also to create lootdrop ID.
# Kiladiveus - In southkarana, need to add loot "19044 Grizzleknot Bark" into "14142 Grizzleknot" with 100% probability. Npc already a rare spawn.      
# items: 3061, 10073, 19031, 19033, 4945, 3053, 19051, 19042, 19040, 4947, 3058, 19052, 19032, 19035, 4948, 3056, 19050, 19036, 19044, 4946


sub EVENT_SAY {
  if($text=~/Hail/i){
    quest::say("Hello. $name! I am the shaman Kyralynn. If you have a banded armor, my husband Vrynn and I can form it into a new shaman armor using this totem and some reagents for the ritual. I can use a banded [bracer], [mail], [helm] or [cloak] to form this new armor.");
  }
  if($text=~/bracer/i){
    quest::say("The bracer requires a banded bracer, 1 dufrenite, a cauldron shell from an aqua goblin lord in Dagnor's Cauldron, and a bull elephant tooth.");
  }
  if($text=~/helm/i){
    quest::say("The helm requires a banded helm, 1 ground dufrenite, a glacier bear pelt, and an ogreskin chamois from a lizard page.");
  }
  if($text=~/cloak/i){
    quest::say("The cloak requires a banded cloak, 1 powdered dufrenite, basalt drake scales, and a driftwood pipe from an isle goblin chieftain.");
  }
  if($text=~/mail/i){
    quest::say("The mail requires banded mail, 1 crushed dufrenite, a lancer swordfish fin, and Grizzleknot bark.");
  }
}

sub EVENT_ITEM {
  if (plugin::check_handin(\%itemcount, 3061 => 1, 10073 => 1, 19031 => 1, 19033 => 1)) {
    quest::exp(200);
    quest::summonitem(4945); # Item: Totemic Bracers
    quest::say("I have crafted your bracer, use it well.");
  }
  elsif (plugin::check_handin(\%itemcount, 3053 => 1, 19051 => 1, 19042 => 1, 19040 => 1)) {
    quest::exp(200);
    quest::summonitem(4947); # Item: Totemic Helm
    quest::say("I have crafted your helm, use it well.");
  }
  elsif (plugin::check_handin(\%itemcount, 3058 => 1, 19052 => 1, 19032 => 1, 19035 => 1)) {
    quest::exp(200);
    quest::summonitem(4948); # Item: Totemic Cloak
    quest::say("I have crafted your cloak, use it well.");
  }
  elsif (plugin::check_handin(\%itemcount, 3056 => 1, 19050 => 1, 19036 => 1, 19044 => 1)) {
    quest::exp(200);
    quest::summonitem(4946); # Item: Totemic Breastplate
    quest::say("I have crafted your breastplate, use it well.");
  }
  plugin::return_items(\%itemcount);
}
#END of FILE Zone:lakerathe  ID:51058 -- Kyralynn

